const rows = $input.all().map((i) => i.json).filter((r) => r.score_id);
const fourteenDaysAgo = Date.now() - 14 * 24 * 60 * 60 * 1000;
const recent = rows.filter((r) => new Date(r.reviewed_at).getTime() >= fourteenDaysAgo);
const strongSingle = rows.find((r) => Number(r.confidence) >= 0.9 && Number(r.persona_alignment_score) <= 2);
const shouldProceed = recent.length >= 2 || !!strongSingle;
return [{ json: { shouldProceed, rows } }];

const text = $('Get Current Persona').first().json.system_prompt || '';
const lines = text.split('\n');
const sections = [];
let current = { heading: '(preamble)', startLine: 0, lines: [] };
for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  if (/^#{2,3}\s+/.test(line)) {
    if (current.lines.length || sections.length === 0) sections.push(current);
    current = { heading: line.replace(/^#{2,3}\s+/, '').trim(), startLine: i, lines: [line] };
  } else {
    current.lines.push(line);
  }
}
sections.push(current);
return [{
  json: {
    sections: sections.map((s) => ({ heading: s.heading, body: s.lines.join('\n') })),
    fullText: text,
  },
}];

const { rows } = $('Require Minimum Evidence').first().json;
const { sections, fullText } = $json;
function overlapScore(section, text) {
  const words = (text || '').toLowerCase().split(/\W+/).filter((w) => w.length > 3);
  const body = section.body.toLowerCase();
  return words.reduce((acc, w) => acc + (body.includes(w) ? 1 : 0), 0);
}
const evidenceText = rows.map((r) => (r.evidence || '') + ' ' + (r.suggested_fix_area || '')).join(' ');
const ranked = sections
  .map((s) => ({ ...s, matchScore: overlapScore(s, evidenceText) }))
  .sort((a, b) => b.matchScore - a.matchScore);
const shortlist = ranked.filter((s) => s.matchScore > 0).slice(0, 2);
const targetSections = shortlist.length ? shortlist : ranked.slice(0, 1);
return [{
  json: { targetSections, allSections: sections, fullText, evidenceText, rows },
}];

