={{ JSON.stringify({
  model: "qwen3:14b",
  stream: false,
  think: false,
  messages: [
    { role: "system", content: "You are proposing a targeted edit to one or more sections of Amy's persona system prompt, based on real review findings. You will be given the full current persona (for context/voice), the section(s) that review evidence points to as the likely cause of a problem, and the evidence itself. Propose a revised body for ONLY the listed section(s) - do not touch anything else, do not add new sections, do not change the heading text. Preserve Amy's existing voice and the rest of the section's intent; make the smallest change that addresses the evidence. If the evidence does not actually justify a change (e.g. it looks like a one-off, or the section already handles it), set shouldPropose to false and explain why in reason. Never invent a claim about what the evidence says - quote or closely paraphrase it in your reasoning." },
    { role: "user", content: "Full current persona (context only, do not edit outside the target section(s)):\n" + $json.fullText + "\n\nTarget section(s) to edit:\n" + JSON.stringify($json.targetSections) + "\n\nEvidence from real conversation reviews:\n" + $json.evidenceText + "\n\nRaw evidence rows:\n" + JSON.stringify($json.rows) }
  ],
  options: { num_ctx: 16384 },
  format: {
    type: "object",
    properties: {
      shouldPropose: { type: "boolean" },
      targetSectionHeadings: { type: "array", items: { type: "string" } },
      editedSectionsMarkdown: {
        type: "array",
        items: {
          type: "object",
          properties: { heading: { type: "string" }, newBody: { type: "string" } },
          required: ["heading", "newBody"]
        }
      },
      reason: { type: "string" }
    },
    required: ["shouldPropose", "reason"]
  }
}) }}

