let parsed;
try {
  parsed = JSON.parse($json.message.content);
} catch (e) {
  parsed = { shouldPropose: false, reason: 'Proposal output failed to parse: ' + e.message, editedSectionsMarkdown: [] };
}
return [{ json: parsed }];

const { allSections } = $('Match Attribution Evidence To Section').first().json;
const proposal = $json;
const edited = new Map((proposal.editedSectionsMarkdown || []).map((e) => [e.heading, e.newBody]));
const rebuilt = allSections.map((s) => (edited.has(s.heading) ? edited.get(s.heading) : s.body)).join('\n');
return [{
  json: {
    proposedSystemPrompt: rebuilt,
    reason: proposal.reason || '',
    targetSectionHeadings: proposal.targetSectionHeadings || [],
  },
}];

const baseline = $('Score Baseline').item.json;
const candidate = $json;
const golden = $('Get Golden Transcripts').item.json;
const dims = ['task_success_score','relevance_score','persona_alignment_score','user_sentiment_score','followup_coherence_score'];
const deltas = {};
let regressed = false;
for (const d of dims) {
  const delta = (candidate[d] ?? 0) - (baseline[d] ?? 0);
  deltas[d] = delta;
  if (delta < -1) regressed = true;
  const floor = (golden.expected_min_scores || {})[d];
  if (floor != null && (candidate[d] ?? 0) < floor) regressed = true;
}
return [{
  json: { label: golden.label, golden_transcript_id: golden.id, baselineScores: baseline, candidateScores: candidate, deltas, regressed },
}];

const results = $input.all().map((i) => i.json);
const anyRegressed = results.some((r) => r.regressed);
const regressedCount = results.filter((r) => r.regressed).length;
const total = results.length;
const lines = results.map((r) => {
  const worst = Object.entries(r.deltas || {}).filter(([, d]) => d < 0).map(([k, d]) => k + ' ' + d).join(', ');
  return r.label + ': ' + (r.regressed ? 'REGRESSED' : 'ok') + (worst ? ' (' + worst + ')' : '');
});
const summary = total === 0
  ? 'No golden transcripts configured - regression check skipped.'
  : anyRegressed
    ? '\u26a0\ufe0f REGRESSION on ' + regressedCount + '/' + total + ' golden transcripts: ' + lines.join('; ')
    : 'Golden regression check: ' + total + '/' + total + ' held or improved.';
return [{ json: { regressionSummary: summary, anyRegressed } }];
